-- Display-only catalog. No Auth accounts, real shops, uploads, bids or orders.
-- App roles read samples only through th_api('snapshot').
begin;
create table if not exists public.th_demo_catalog (
 kind text not null check(kind in ('product','store')),
 id text not null,ordinal integer not null,
 data jsonb not null check(jsonb_typeof(data)='object' and data->'isDemo'='true'::jsonb),
 primary key(kind,id),check(data->>'id'=id)
);
alter table public.th_demo_catalog enable row level security;
revoke all on public.th_demo_catalog from public,anon,authenticated;

